select dept_id as deptId,
       dept_name as deptName,
       COUNT(*) as editCount,
       MIN(operation_time) as firstEditTime,
       MAX(operation_time) as lastEditTime
from luckysheet_cell_history
where workbook_id = #{workbookId}
  and sheet_index = #{sheetIndex}
  and row_index = #{rowIndex}
  and col_index = #{colIndex}
  and operation_type IN ('INSERT', 'UPDATE')
group by dept_id, dept_name
order by editCount desc
